local a=base:get(np.s(1,nil,2))
local lo=0.0
local hi=-0.0
local ok,result=pcall(function()return np.clip(a,lo,hi)end)
assert(ok==true,"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: acceptance"..": "..tostring(result))
eq(result:tolist(),{{0.0,-0.0,0.0}},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: values")
eq(result.shape,{1,3},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: shape")
eq(result.strides,{24,8},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: strides")
eq(result.dtype,"float64","clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: dtype")
eq(np.logical_and(np.signbit(result),np.equal(result,0)):tolist(),{{false,true,false}},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: signed zero")
eq(np.shares_memory(result,a),false,"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: no sharing")
eq(a:tolist(),{{false,true,false}},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: values")
eq(a.shape,{1,3},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: shape")
eq(a.strides,{6,1},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: strides")
eq(a.dtype,"bool","clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: dtype")
eq(base:tolist(),{{false,true,false},{true,false,true}},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: values")
eq(base.shape,{2,3},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: shape")
eq(base.strides,{3,1},"clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: strides")
eq(base.dtype,"bool","clip/bool(2, 3)/step_first/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: dtype")
cases=cases+1
end
