local a=np.broadcast_to(base:get(np.s(1,2),np.s(1,2)),base.shape)
local lo=false
local hi=true
local ok,result=pcall(function()return np.clip(a,lo,hi)end)
assert(ok==true,"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: acceptance"..": "..tostring(result))
eq(result:tolist(),{{false,false,false},{false,false,false}},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: result: values")
eq(result.shape,{2,3},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: result: shape")
eq(result.strides,{3,1},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: result: strides")
eq(result.dtype,"bool","clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: result: dtype")
eq(np.shares_memory(result,a),false,"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: no sharing")
eq(a:tolist(),{{false,false,false},{false,false,false}},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: input: values")
eq(a.shape,{2,3},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: input: shape")
eq(a.strides,{0,0},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: input: strides")
eq(a.dtype,"bool","clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: input: dtype")
eq(base:tolist(),{{false,true,false},{true,false,true}},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: backing: values")
eq(base.shape,{2,3},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: backing: shape")
eq(base.strides,{3,1},"clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: backing: strides")
eq(base.dtype,"bool","clip/bool(2, 3)/constant/['False', 'True']/weak(True, True)/new/float64/maskFalse: backing: dtype")
cases=cases+1
end
