local a=base:get(np.s(),np.s(1,nil,2))
local lo=0.0
local hi=-0.0
local ok,result=pcall(function()return np.clip(a,lo,hi)end)
assert(ok==true,"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: acceptance"..": "..tostring(result))
eq(result:tolist(),{{0.0,-0.0},{-0.0,-0.0}},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: values")
eq(result.shape,{2,2},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: shape")
eq(result.strides,{16,8},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: strides")
eq(result.dtype,"float64","clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: dtype")
eq(np.logical_and(np.signbit(result),np.equal(result,0)):tolist(),{{false,true},{true,true}},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: result: signed zero")
eq(np.shares_memory(result,a),false,"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: no sharing")
eq(a:tolist(),{{0,2},{3,5}},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: values")
eq(a.shape,{2,2},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: shape")
eq(a.strides,{3,2},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: strides")
eq(a.dtype,"uint8","clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: input: dtype")
eq(base:tolist(),{{0,1,2},{3,4,5}},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: values")
eq(base.shape,{2,3},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: shape")
eq(base.strides,{3,1},"clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: strides")
eq(base.dtype,"uint8","clip/uint8(2, 3)/step_last/['0.0', '-0.0']/weak(True, True)/new/float64/maskFalse: backing: dtype")
cases=cases+1
end
