local ok,result=pcall(function()return np.clip(a,lo,hi)end)
assert(ok==true,"clip/int8(2, 3)/reverse_last/['float64()', '-0.0']/weak(False, True)/new/float64/maskFalse: acceptance"..": "..tostring(result))
