eq(lo:tolist(),0.0,"clip/int8(2, 3)/reverse_last/['float64()', '-0.0']/weak(False, True)/new/float64/maskFalse: bound lo: values")
eq(lo.shape,{},"clip/int8(2, 3)/reverse_last/['float64()', '-0.0']/weak(False, True)/new/float64/maskFalse: bound lo: shape")
eq(lo.strides,{},"clip/int8(2, 3)/reverse_last/['float64()', '-0.0']/weak(False, True)/new/float64/maskFalse: bound lo: strides")
