eq(a.dtype,"int8","clip/int8(2, 3)/reverse_last/['float64()', '-0.0']/weak(False, True)/new/float64/maskFalse: input: dtype")
eq(base:tolist(),{{0,1,2},{3,4,5}},"clip/int8(2, 3)/reverse_last/['float64()', '-0.0']/weak(False, True)/new/float64/maskFalse: backing: values")
