eq(lo.dtype,"float16","clip/uint16(2, 3)/base/['float16(2, 1)', '2.0']/weak(False, True)/new/float64/maskFalse: bound lo: dtype")
eq(np.logical_and(np.signbit(lo),np.equal(lo,0)):tolist(),{{false},{false}},"clip/uint16(2, 3)/base/['float16(2, 1)', '2.0']/weak(False, True)/new/float64/maskFalse: bound lo: signed zero")
